// Stock replenishment — see specs/shared/n8n-workflows.md §5.
// Tops up on-hand units for every low-stock item, grouped by company.
// No fact is emitted (§5.1) — this is an operational act outside any saga.

const gatewayUrl = ($env.OTC_GATEWAY_URL || 'http://gateway:3001').replace(/\/$/, '');
const username = $env.GATEWAY_OPERATOR_USERNAME;
const password = $env.GATEWAY_OPERATOR_PASSWORD;
const timeoutMs = Number($env.OTC_REQUEST_TIMEOUT_MS || 10000);

const enabled = ($env.STOCK_REPLENISH_ENABLED ?? 'true') !== 'false';
const topUpUnits = Number($env.STOCK_REPLENISH_TOP_UP_UNITS || 100);
const batchSize = Number($env.STOCK_REPLENISH_BATCH_SIZE || 50);
const companyFilter = ($env.STOCK_REPLENISH_COMPANIES || '').split(',').map((s) => s.trim()).filter(Boolean);

if (!enabled) {
  return [{ json: { skipped: true, reason: 'STOCK_REPLENISH_ENABLED=false' } }];
}

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

async function requestWithRetry(options, { retryOn5xxAndNetwork = true } = {}) {
  const attempts = retryOn5xxAndNetwork ? 4 : 1;
  let lastErr;
  for (let attempt = 0; attempt < attempts; attempt += 1) {
    try {
      return await this.helpers.httpRequest({ timeout: timeoutMs, ...options });
    } catch (err) {
      lastErr = err;
      const status = err.status ?? err.response?.status;
      const isNetworkError = status === undefined;
      const is5xx = typeof status === 'number' && status >= 500;
      if (!retryOn5xxAndNetwork || !(isNetworkError || is5xx) || attempt === attempts - 1) {
        throw err;
      }
      await sleep(2 ** attempt * 250);
    }
  }
  throw lastErr;
}

async function login() {
  const res = await requestWithRetry.call(this, {
    method: 'POST', url: `${gatewayUrl}/auth/login`, body: { username, password }, json: true,
  });
  return res.accessToken;
}

function authHeaders(token) {
  return { Authorization: `Bearer ${token}` };
}

async function listLowStock(token) {
  const res = await requestWithRetry.call(this, {
    method: 'GET', url: `${gatewayUrl}/stock`,
    headers: authHeaders(token),
    qs: { belowThreshold: true, pageSize: batchSize },
    json: true,
  });
  let items = res.items;
  if (companyFilter.length) items = items.filter((i) => companyFilter.includes(i.companyCode));
  return items;
}

function groupByCompany(items) {
  const groups = new Map();
  for (const item of items) {
    if (!groups.has(item.companyCode)) groups.set(item.companyCode, []);
    groups.get(item.companyCode).push(item);
  }
  return groups;
}

async function replenishCompany(token, companyCode, items) {
  const body = {
    companyCode,
    lines: items.map((i) => ({ productCode: i.productCode, units: topUpUnits })),
  };
  const res = await requestWithRetry.call(this, {
    method: 'POST', url: `${gatewayUrl}/stock/replenish`, headers: authHeaders(token), body, json: true,
  });
  return { companyCode, itemsToppedUp: res.items.length };
}

async function run() {
  const token = await login.call(this);
  const lowItems = await listLowStock.call(this, token);
  if (lowItems.length === 0) return [{ companyCode: null, itemsToppedUp: 0, message: 'no low-stock items' }];
  const groups = groupByCompany(lowItems);
  const results = [];
  for (const [companyCode, items] of groups) {
    try {
      results.push(await replenishCompany.call(this, token, companyCode, items));
    } catch (err) {
      results.push({ companyCode, outcome: 'error', message: err.message, status: err.status ?? err.response?.status });
    }
  }
  return results;
}

const runResults = await run.call(this);
return runResults.map((r) => ({ json: r }));
